vcard-edit {
  display: grid;
  display: grid-lanes;
  grid-template-columns: repeat(auto-fill, minmax(30em, 1fr));
  column-gap: 2em;
  row-gap: var(--vcard-edit-row-gap);
  color: var(--sidebar-color);
  --input-border-density: 1px;

  & label[for] {
    margin-block-end: 6px;
    font-weight: 600;
  }

